import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const TYPES = ['ALERT', 'MENTION'];

function isId(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isInteger(v) && v > 0;
  }
  return typeof v === 'string' && /^[0-9]+$/.test(v);
}

function requiredText(v: unknown, max: number): string {
  if (typeof v !== 'string' || v.trim() === '' || v.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', '필수 값이 없거나 형식이 올바르지 않습니다.');
  }
  return v;
}

@Controller('api/v1')
export class FnSfr02801Controller {
  @Get('/notifications')
  async listNotifications(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const rawType = query['notificationType'];
    let type: string | null = null;
    if (rawType !== undefined && rawType !== null && rawType !== '') {
      if (typeof rawType !== 'string' || !TYPES.includes(rawType)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '알림 구분이 올바르지 않습니다.');
      }
      type = rawType;
    }
    const rawPage = query['page'];
    const rawSize = query['size'];
    const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
    const size = rawSize === undefined || rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    return transaction(async (db) => {
      const params = {
        userId: user.id,
        type,
        limit,
        offset: page * limit,
      };
      const rows = await db.query(
        `SELECT notification_id AS "notificationId",
                notification_type AS "notificationType",
                event_type AS "eventType",
                title AS "title",
                summary AS "summary",
                target_type AS "targetType",
                target_id AS "targetId",
                read_yn AS "readYn",
                occurred_at AS "occurredAt"
           FROM notification
          WHERE employee_id = CAST(:userId AS bigint)
            AND (CAST(:type AS varchar) IS NULL OR notification_type = CAST(:type AS varchar))
          ORDER BY occurred_at DESC, notification_id DESC
          LIMIT :limit OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM notification
          WHERE employee_id = CAST(:userId AS bigint)
            AND (CAST(:type AS varchar) IS NULL OR notification_type = CAST(:type AS varchar))`,
        { userId: user.id, type },
      );
      return {
        items: rows,
        page,
        size: limit,
        total: Number(counts[0]?.total ?? 0),
      };
    });
  }

  @Post('/notifications/mentions')
  @HttpCode(200)
  async createMentionNotification(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    if (!isId(data['employeeId']) || !isId(data['targetId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '수신자 또는 바로가기 대상 식별자가 올바르지 않습니다.');
    }
    const eventType = requiredText(data['eventType'], 50);
    const title = requiredText(data['title'], 300);
    const targetType = requiredText(data['targetType'], 50);
    const rawDetail = data['detail'];
    if (rawDetail !== undefined && rawDetail !== null && typeof rawDetail !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '상세내용 형식이 올바르지 않습니다.');
    }
    const detail = typeof rawDetail === 'string' && rawDetail !== '' ? rawDetail : null;
    return transaction(async (db) => {
      // 멘션 대상이 존재하고 재직 중인지 먼저 확인한다 (가정: 재직자만 사용 권한이 있음)
      const targets = await db.query(
        `SELECT employee_id AS "employeeId"
           FROM employee
          WHERE employee_id = CAST(:employeeId AS bigint)
            AND employment_status = '재직'`,
        { employeeId: String(data['employeeId']) },
      );
      if (targets.length === 0) {
        throw new ApiError(422, 'MENTION_TARGET_INVALID', '멘션 대상이 존재하지 않거나 사용 권한이 없습니다.');
      }
      const rows = await db.query(
        `INSERT INTO notification (
           employee_id, notification_type, event_type, title, detail,
           target_type, target_id, read_yn, occurred_at, created_at, updated_at
         ) VALUES (
           CAST(:employeeId AS bigint), 'MENTION', :eventType, :title, :detail,
           :targetType, CAST(:targetId AS bigint), false, now(), now(), now()
         )
         RETURNING notification_id AS "notificationId"`,
        {
          employeeId: String(data['employeeId']),
          eventType,
          title,
          detail,
          targetType,
          targetId: String(data['targetId']),
        },
      );
      return { notificationId: Number(rows[0].notificationId) };
    });
  }
}

