import { useState } from 'react';
import {
  call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager,
  Drawer, Pairs, Tiles, Form, Field, TextInput, Select, LookupSelect,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr02801Page({ role, notify }: PageProps) {
  const [type, setType] = useState('');
  const [applied, setApplied] = useState('');
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [eventType, setEventType] = useState('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/notifications', role, undefined, {
      notificationType: applied,
      page,
      size: SIZE,
    }),
    [role, applied, page],
  );

  const typeOptions: [string, string][] = [
    ['ALERT', '알림'],
    ['MENTION', '@멘션'],
  ];

  const openCreate = () => {
    setEmployeeId('');
    setEventType('');
    setTitle('');
    setBody('');
    setTargetType('');
    setTargetId('');
    setCreating(true);
  };

  const submit = async () => {
    if (employeeId === '' || !eventType.trim() || !title.trim() || !targetType.trim() || targetId.trim() === '') {
      throw new Error('수신자, 연계 이벤트 유형, 제목, 바로가기 대상 유형·식별자를 모두 입력하세요.');
    }
    await call('POST', '/notifications/mentions', role, {
      employeeId,
      eventType,
      title,
      detail: body,
      targetType,
      targetId: Number(targetId),
    });
    notify('멘션 알림을 생성했습니다.');
    setCreating(false);
    list.reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>알림 현황</h2>
        <Tiles items={[['조회 건수', <Num value={list.data?.total ?? 0} />]]} />
      </section>
      <section className="box span-12">
        <h2>통합 알림</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied(type);
          }}
          onReset={() => {
            setType('');
            setApplied('');
            setPage(0);
          }}
        >
          <Field label="알림 구분">
            <Select value={type} onChange={setType} options={typeOptions} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={openCreate}>멘션 알림 등록</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={list.data?.items ?? []}
          empty="알림이 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'notificationType', label: '알림 구분', render: (r) => <Badge value={r.notificationType === 'MENTION' ? '@멘션' : '알림'} /> },
            { key: 'eventType', label: '연계 이벤트 유형' },
            { key: 'title', label: '제목' },
            { key: 'summary', label: '요약' },
            { key: 'readYn', label: '읽음 여부', render: (r) => <Badge value={r.readYn ? '읽음' : '안 읽음'} /> },
            { key: 'occurredAt', label: '이벤트 발생 일시', render: (r) => <DateText value={r.occurredAt} time /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      {detail ? (
        <Drawer title="알림 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['알림 ID', String(detail.notificationId)],
              ['알림 구분', <Badge value={detail.notificationType === 'MENTION' ? '@멘션' : '알림'} />],
              ['연계 이벤트 유형', String(detail.eventType ?? '')],
              ['제목', String(detail.title ?? '')],
              ['요약', String(detail.summary ?? '')],
              ['바로가기 대상 유형', String(detail.targetType ?? '')],
              ['바로가기 대상 식별자', String(detail.targetId ?? '')],
              ['읽음 여부', <Badge value={detail.readYn ? '읽음' : '안 읽음'} />],
              ['이벤트 발생 일시', <DateText value={detail.occurredAt} time />],
            ]}
          />
        </Drawer>
      ) : null}
      {creating ? (
        <Drawer title="멘션 알림 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="등록">
            <Field label="수신자" required>
              <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
            <Field label="연계 이벤트 유형" required>
              <TextInput value={eventType} onChange={setEventType} />
            </Field>
            <Field label="제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="상세내용" wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label="바로가기 대상 유형" required>
              <TextInput value={targetType} onChange={setTargetType} />
            </Field>
            <Field label="바로가기 대상 식별자" required>
              <TextInput value={targetId} onChange={setTargetId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
